#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <num_nodes> <edge1> <edge2> ...\n", argv[0]);
        return 1;
    }

    int num_nodes = atoi(argv[1]);
    int adj[num_nodes][num_nodes] = {{0}};
    int indegree[num_nodes] = {0};
    int done[num_nodes] = {0};

    for (int i = 2; i < argc; i += 2) {
        int u = atoi(argv[i]);
        int v = atoi(argv[i + 1]);
        adj[u][v] = 1;
        indegree[v] ++;
    }

    int queue[8];
    int front = 0, rear = 0;
    for (int i = 0; i < num_nodes; i++) {
        if (indegree[i] == 0) {
            queue[rear++] = i;
        }
    }

    while (front < rear) {
        int u = queue[front++];
        printf("%d ", u);
        for (int v = 0; v < num_nodes; v++) {
            if (adj[u][v]) {
                indegree[v] --;
                if (indegree[v] == 0) {
                    queue[rear++] = v;
                }
            }
        }
    }

    printf("\n");
    return 0;
}
